86: kitchenModal(espresso?'Your espresso, step by step':recipe.name,`STEP ${Math.min(step+1,3)} OF 3 · ${stages[Math.min(step,2)]}`,content);if(step<2){$('#ritualNext').onclick=()=>{const needed=espresso&&step===1?1:3;if(state.prep<needed){state.prep++;show()}else{state.step++;state.prep=0;show()}}}else if(step===2){let marker=$('#timingMarker');const timer=setInterval(()=>{if(!marker?.isConnected){clearInterval(timer);return}state.bar+=state.direction*2.7;if(state.bar>=100||state.bar<=0)state.direction*=-1;marker.style.left=`${state.bar}%`},28);$('#ritualStop').onclick=()=>{clearInterval(timer);state.quality=state.bar>=40&&state.bar<=64?3:state.bar>=25&&state.bar<=78?2:1;state.step=3;show()}}else $('#ritualServe').onclick=()=>finishKitchenGame(kind,recipe,state.quality)}show()}
87: function finishKitchenGame(kind,recipe,quality){if(!spend()){closeModal();return}if(kind==='espresso'){consume({Beans:1});game.points+=10+quality*2;game.stats.drinks++;complete('drink');toast(`A lovely espresso, poured just right. +${10+quality*2} drops`)}else{consume(recipe.cost);game.inventory['Cat food']=(game.inventory['Cat food']||0)+1;game.points+=recipe.reward+quality*2;game.stats.recipes++;complete(recipe.task);toast(`${recipe.name} is ready! A little portion for ${game.cats[game.cat].name}. +${recipe.reward+quality*2} drops`)}if(game.stats.recipes>=5)announceAchievement('homecook','Home Kitchen','Made five recipes');closeModal();save()}
