33:         <p class="ritual-instruction">${stages[step]}</p>
34:         <p class="ritual-sub">${subs[step]}</p>
35:         <div class="prep-dots">${Array.from({ length: needed }, (_, i) => `<i class="${i < state.prep ? 'filled' : ''}"></i>`).join('')}</div>
36:         <button class="ritual-button" id="ritualNext">${state.prep >= needed ? 'Continue →' : 'Tap to prepare'}</button>`;
37:     } else if (step === 2) {
