81: function tickWalk(dt) {
82:   const p = playerPosition();
83:   if (p.tx == null) { p.walking = false; return; }
84:   const dx = p.tx - p.x, dy = p.ty - p.y;
85:   const d = Math.hypot(dx, dy);
86:   const step = Math.min(0.18 * dt, d);
87:   if (d < 1.5) {
88:     p.x = p.tx; p.y = p.ty;
89:     delete p.tx; delete p.ty;
90:     p.walking = false;
91:     if (p.auto) { delete p.auto; interact(); }
92:     save();
93:     return;
94:   }
95:   p.x += dx / d * step;
96:   p.y += dy / d * step;
97:   p.walking = true;
98:   if (Math.abs(dx) > 1) p.face = dx < 0 ? -1 : 1;
99: }
